@@ -110,6 +110,7 @@ fn unnecessary_spread_fix(

     if let Some(last) = dict.iter_values().last() {
         let last_end = last.end();
+        let leading_edit = Edit::range_deletion(doublestar.range());
         let mut edits = Vec::new();
         for tok in SimpleTokenizer::starts_at(last_end, source) {
             let kind = tok.kind();
@@ -129,9 +130,38 @@ fn unnecessary_spread_fix(
                 _ => {}
             }
         }
-        let leading_start = doublestar.start();
-        let open_brace = dict.start() + TextSize::from(1);
-        let leading_edit = Edit::deletion(leading_start, open_brace);
+
+        // The inner dictionary can be parenthesized (for example, `**({"key": value})`).
+        // Delete only its punctuation so that comments between the parentheses are preserved.
+        let mut parentheses = 0;
+        for tok in SimpleTokenizer::starts_at(doublestar.end(), source) {
+            match tok.kind() {
+                SimpleTokenKind::LParen => {
+                    edits.push(Edit::range_deletion(tok.range()));
+                    parentheses += 1;
+                }
+                SimpleTokenKind::LBrace => {
+                    edits.push(Edit::range_deletion(tok.range()));
+                    break;
+                }
+                _ if !tok.kind().is_trivia() => return None,
+                _ => {}
+            }
+        }
+        if parentheses > 0 {
+            for tok in SimpleTokenizer::starts_at(last_end, source) {
+                if tok.kind().is_trivia() {
+                    continue;
+                }
+                if tok.kind() == SimpleTokenKind::RParen {
+                    edits.push(Edit::range_deletion(tok.range()));
+                    parentheses -= 1;
+                    if parentheses == 0 {
+                        break;
+                    }
+                }
+            }
+        }
         Some(Fix::safe_edits(leading_edit, edits))
     } else {
         let deletion_start = doublestar.start();
 M crates/ruff_linter/src/rules/flake8_pie/rules/unnecessary_spread.rs

